import javax.swing.JPanel;

/**
 * TASK: Count only the LETTER keys a user types.
 *
 * Register a KeyListener on this panel. In keyTyped, look at e.getKeyChar():
 *   - if Character.isLetter(...) is true, add 1 to the counter and remember
 *     that character as the last letter
 *   - otherwise ignore the key completely (digits, punctuation, spaces)
 *
 * KeyListener has three methods (keyTyped, keyPressed, keyReleased); extending
 * java.awt.event.KeyAdapter and overriding only keyTyped keeps it short.
 *
 * Example: typing 'j', '7', 'v'
 *   count()    -> 2
 *   lastChar() -> 'v'
 * Before any letter is typed, lastChar() returns a space ' '.
 *
 * No window is ever opened -- the tests build KeyEvents by hand and hand them
 * straight to the registered listener.
 */
public class KeyCounter extends JPanel {

    private int letters = 0;
    private char last = ' ';

    public KeyCounter() {
        // TODO: addKeyListener(...) so keyTyped counts letters and stores the
        // most recent letter
    }

    public int count() {
        // TODO: return how many letters have been typed
        return 0;
    }

    public char lastChar() {
        // TODO: return the most recent letter (' ' if there has not been one)
        return ' ';
    }
}

