import java.awt.event.KeyEvent;
import java.awt.event.KeyListener;

public class KeyCounterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void type(KeyCounter panel, char ch) {
        KeyEvent event = new KeyEvent(panel, KeyEvent.KEY_TYPED,
                System.currentTimeMillis(), 0, KeyEvent.VK_UNDEFINED, ch);
        for (KeyListener listener : panel.getKeyListeners()) {
            listener.keyTyped(event);
        }
    }

    public static void main(String[] args) {
        try {
            KeyCounter panel = new KeyCounter();
            check("a KeyListener is registered", true, panel.getKeyListeners().length >= 1);
            check("count starts at 0", 0, panel.count());
            check("lastChar starts as a space", ' ', panel.lastChar());

            type(panel, 'j');
            check("count after one letter", 1, panel.count());
            check("lastChar after one letter", 'j', panel.lastChar());

            type(panel, '7');
            check("digits are ignored", "1 j", panel.count() + " " + panel.lastChar());

            type(panel, ' ');
            type(panel, '!');
            check("space and punctuation are ignored", 1, panel.count());

            type(panel, 'v');
            type(panel, 'Q');
            check("count and lastChar after more letters", "3 Q",
                    panel.count() + " " + panel.lastChar());
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected " + t.getClass().getSimpleName() + ": " + t.getMessage());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

